function Fail([string]$Message) { throw "FAIL: $Message" }

function Sha([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path)) { return "FILE_MISSING" }
    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant()
}

function ReadT([string]$Path) {
    return [IO.File]::ReadAllText((Resolve-Path -LiteralPath $Path))
}

function WriteUtf8NoBom([string]$Path,[string]$Text) {
    $Parent = Split-Path -Parent $Path
    if ($Parent) { New-Item -ItemType Directory -Force -Path $Parent | Out-Null }
    [IO.File]::WriteAllText($Path,$Text,[Text.UTF8Encoding]::new($false))
}

function WritePayload([string]$Path,[string]$Base64) {
    $Text = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64))
    WriteUtf8NoBom $Path $Text
}

function Replace-Once([string]$Text,[string]$Old,[string]$New,[string]$Label) {
    $Count = ([regex]::Matches($Text,[regex]::Escape($Old))).Count
    if ($Count -ne 1) {
        Fail "$Label expected exactly one anchor, found $Count"
    }
    return $Text.Replace($Old,$New)
}

function Hash-Protected([string[]]$Intentional,[string]$Output) {
    $Rows = New-Object System.Collections.Generic.List[string]
    $Tracked = & git ls-files app
    if ($LASTEXITCODE -ne 0) { Fail "git ls-files app failed" }
    foreach ($RelUnix in $Tracked) {
        $Rel = $RelUnix.Replace('/','\')
        if ($Intentional -contains $Rel) { continue }
        if (Test-Path -LiteralPath $Rel) {
            $Rows.Add(("{0}  {1}" -f (Sha $Rel),$RelUnix))
        } else {
            $Rows.Add(("FILE_MISSING  {0}" -f $RelUnix))
        }
    }
    $Rows | Sort-Object | Set-Content -LiteralPath $Output -Encoding UTF8
}

function Find-JavaMethodEnd([string]$Text,[int]$MethodStart) {
    $Brace = $Text.IndexOf('{',$MethodStart)
    if ($Brace -lt 0) { Fail "Java method opening brace not found" }

    $Depth = 0
    $State = "code"
    $i = $Brace
    while ($i -lt $Text.Length) {
        $c = $Text[$i]
        $n = if ($i + 1 -lt $Text.Length) { $Text[$i+1] } else { [char]0 }

        switch ($State) {
            "code" {
                if ($c -eq '/' -and $n -eq '/') { $State="line"; $i+=2; continue }
                if ($c -eq '/' -and $n -eq '*') { $State="block"; $i+=2; continue }
                if ($c -eq '"') { $State="string"; $i++; continue }
                if ($c -eq "'") { $State="char"; $i++; continue }
                if ($c -eq '{') { $Depth++ }
                elseif ($c -eq '}') {
                    $Depth--
                    if ($Depth -eq 0) { return $i + 1 }
                }
            }
            "line" {
                if ($c -eq "`n") { $State="code" }
            }
            "block" {
                if ($c -eq '*' -and $n -eq '/') { $State="code"; $i+=2; continue }
            }
            "string" {
                if ($c -eq '\') { $i+=2; continue }
                if ($c -eq '"') { $State="code" }
            }
            "char" {
                if ($c -eq '\') { $i+=2; continue }
                if ($c -eq "'") { $State="code" }
            }
        }
        $i++
    }
    Fail "Java method closing brace not found"
}

