# ---------------- ImageSaver 26431 + 26432 candidate ----------------
$CI = Join-Path $Cand $IMAGESAVER
$I = ReadT $CI
if ($I.Contains('saveBitmapAsJPGMotionV2(')) { Fail "ImageSaver Motion helper already exists unexpectedly" }

$Needle = 'public static boolean saveBitmapAsJPG('
$MethodStart = $I.IndexOf($Needle)
if ($MethodStart -lt 0) { Fail "ImageSaver saveBitmapAsJPG missing" }
$MethodEnd = Find-JavaMethodEnd $I $MethodStart

$Helper = @'

        /** IRIS_26432_MOTION_V2_DIRECT_GAINMAP_JPEG */
        public static boolean saveBitmapAsJPGMotionV2(
                Path fileToSave,
                Bitmap img,
                int jpgQuality,
                ParseExif.ExifData exifData) {
            exifData.COMPRESSION = String.valueOf(jpgQuality);
            try {
                boolean saved;
                try (OutputStream outputStream = Files.newOutputStream(fileToSave)) {
                    saved = img.compress(
                            Bitmap.CompressFormat.JPEG,
                            jpgQuality,
                            outputStream);
                    outputStream.flush();
                }
                if (!saved) return false;

                img.recycle();
                ExifInterface inter = ParseExif.setAllAttributes(
                        fileToSave.toFile(), exifData);
                inter.saveAttributes();
                return true;
            } catch (IOException e) {
                e.printStackTrace();
                return false;
            }
        }
'@
$I = $I.Substring(0,$MethodEnd) + $Helper + $I.Substring($MethodEnd)
WriteUtf8NoBom $CI $I

