    public ByteBuffer motionV2FloatCfa;

    /* IRIS_26432_TRUE_V2_GAINMAP_HANDOFF */
    public Bitmap motionV2GainMapBitmap;
    public float motionV2GainMapMaxRatio = 1.0f;
'@ `
    'PostPipeline gain-map fields'

$OldReturn = @'
        GLImage resImg = runAll();
        Bitmap res = resImg.getBufferedImage();
        Allocator.free(resImg.byteBuffer);
        GLTexture.closeAll();
        return res;
'@
$NewReturn = @'
        GLImage resImg = runAll();
        Bitmap res = resImg.getBufferedImage();

        /*
         * IRIS_26432_TRUE_V2_ULTRAHDR_ATTACH
         * Gain map came from pre-tone extended-linear Motion V2 signal.
         */
        if (mParameters.motionV2Active && motionV2GainMapBitmap != null) {
            boolean attached = MotionV2UltraHdr.attach(
                    res,
                    motionV2GainMapBitmap,
                    getRotation(),
                    motionV2GainMapMaxRatio);
            try {
                com.particlesdevs.photoncamera.util.MotionTrace.processingState(
                        "IRIS_26432_TRUE_V2_ULTRAHDR",
                        "attached=" + attached
                                + " source=extendedLinearPreTone"
                                + " sdrBasePreserved=true"
                                + " bodyGainUnity=true"
                                + " maxRatio=" + motionV2GainMapMaxRatio);
            } catch (Throwable ignored) {}
            motionV2GainMapBitmap = null;
        }

        Allocator.free(resImg.byteBuffer);
        GLTexture.closeAll();
        return res;
'@
$P = Replace-Once $P $OldReturn $NewReturn 'PostPipeline UltraHDR attach'
WriteUtf8NoBom $CP $P

Write-Host "=== GATE 2A: CROSS-BUILD VISUAL + ARCHITECTURE PROOF ==="

$Checks = @(
    @{F=$DINIT; M='IRIS_26436_REFERENCE_SEEDED_TEMPORAL_CONSENSUS_INIT'},
    @{F=$DINIT; M='IRIS_26429_REFERENCE_STRUCTURE_COLOR_SAFETY'},
    @{F=$DACC; M='IRIS_26436_REFERENCE_SEEDED_TEMPORAL_CONSENSUS'},
    @{F=$DACC; M='IRIS_26436_REFERENCE_RESIDUAL_SHARED_COLOR_MERGE'},
    @{F=$DACC; M='alignmentResidualTrust'},
    @{F=$DACC; M='temporalTrust'},
    @{F=$RECON; M='IRIS_26436_REFERENCE_TIME_ORDERED_TEMPORAL_CONSENSUS'},
    @{F=$RECON; M='IRIS_26436_PERMANENT_SPATIAL_SUPPORT_TELEMETRY'},
    @{F=$ALIGNJ; M='IRIS_26436_PERMANENT_ALIGNMENT_TELEMETRY'},
    @{F=$ALIGNF; M='IRIS_26436_REFERENCE_RIGID_LOCAL_ALIGNMENT'},
    @{F=$HDRX; M='IRIS_26431_MOTION_V2_ALL_FRAME_HANDOFF'},
    @{F=$HDRX; M='targetFraction=1.0'},
    @{F=$HDRX; M='globalGyroDiscard=false'},
    @{F=$POST; M='IRIS_26432_TRUE_V2_ULTRAHDR_ATTACH'},
    @{F=$COLORJ; M='IRIS_26430_MOTION_V2_COLOR_SAFETY_ONLY'},
    @{F=$COLORG; M='IRIS_26430_SENSOR_CLIP_COLOR_SAFETY_ONLY'},
    @{F=$DENOISEJ; M='IRIS_26430_MOTION_V2_OWNED_RESIDUAL_CLEANUP'},
    @{F=$DENOISEG; M='IRIS_26430_LIGHT_SUPPORT_OWNED_RESIDUAL_CLEANUP'},
    @{F=$RENDERG; M='IRIS_26435_EXACT_26430_HEADROOM_BASE_MINUS_032EV'},
    @{F=$GAINMAP; M='IRIS_26436_BROAD_REGION_CHROMA_PROTECTED_GAINMAP'},
    @{F=$UHDR; M='IRIS_26436_MOTION_V2_CHROMA_SAFE_ULTRAHDR'}
)
foreach ($C in $Checks) {
    $Text = ReadT (Join-Path $Cand $C.F)
    if (-not $Text.Contains($C.M)) { Fail "Candidate missing $($C.M) in $($C.F)" }
}

$Acc = ReadT (Join-Path $Cand $DACC)
if ($Acc.Contains('perFrameCap')) { Fail "Hard per-frame cap returned" }
if ($Acc.Contains('referenceCeiling')) { Fail "Hard support ceiling returned" }
if ($Acc -match '\bcur\.r\b') { Fail "Evolving RGB entered motion trust" }

$Flow = ReadT (Join-Path $Cand $ALIGNF)
if ($Flow.Contains('mix(0.48,1.0')) { Fail "Old artificial confidence floor survived" }
if (-not $Flow.Contains('if(best>0.070) confidence=0.0')) { Fail "Bad-patch zero confidence missing" }

$Render = ReadT (Join-Path $Cand $RENDERJ)
if (-not $Render.Contains('OUTPUT_EXPOSURE_SCALE = 0.80f')) { Fail "0.80 exposure scale missing" }
if (-not $Render.Contains('Math.min(2.5f, OUTPUT_EXPOSURE_SCALE * canonicalSensorWhite)')) { Fail "2.5x HDR cap missing" }

$VersionCandidate = ReadT (Join-Path $Cand $VERSION)
if ($VersionCandidate -notmatch '(?m)^VERSION_NAME=0\.9726436\r?$' -or
    $VersionCandidate -notmatch '(?m)^VERSION_BUILD=26436\r?$') {
    Fail "Candidate version is not 0.9726436 / 26436"
}

Write-Host "candidate/source validation PASS"
Write-Host "Temporary-copy validation: PASS"

Write-Host "=== GATE 3: REAL GLSL VALIDATION ==="
$Validator = $null
$Cmd = Get-Command glslangValidator.exe -ErrorAction SilentlyContinue
if ($Cmd) { $Validator = $Cmd.Source }

if (-not $Validator) {
    $Candidates = @(
        'C:\VulkanSDK\*\Bin\glslangValidator.exe',
        'C:\VulkanSDK\*\Bin32\glslangValidator.exe'
    )
    foreach ($Pattern in $Candidates) {
        $Hit = Get-ChildItem -Path $Pattern -ErrorAction SilentlyContinue |
            Sort-Object FullName -Descending |
            Select-Object -First 1
        if ($Hit) { $Validator = $Hit.FullName; break }
    }
}
if (-not $Validator) {
    Fail "glslangValidator.exe not found. Install Vulkan SDK or add glslangValidator to PATH; source has NOT been modified."
}

$GlslLog = Join-Path $Safety "glslang_26436_windows.txt"
$ShaderFiles = @(
    @{P=(Join-Path $Cand $ALIGNF); S='comp'},
    @{P=(Join-Path $Cand $DINIT); S='comp'},
    @{P=(Join-Path $Cand $DACC); S='comp'},
    @{P=(Join-Path $Cand $COLORG); S='frag'},
    @{P=(Join-Path $Cand $DENOISEG); S='frag'},
    @{P=(Join-Path $Cand $RENDERG); S='frag'},
    @{P=(Join-Path $Cand $GAINMAP); S='frag'}
)

$WrapDir = Join-Path $Safety "glsl_wrapped"
New-Item -ItemType Directory -Force -Path $WrapDir | Out-Null
$GlslOutput = New-Object System.Collections.Generic.List[string]

foreach ($Item in $ShaderFiles) {
    $Text = ReadT $Item.P
    if ($Item.S -eq 'comp') {
        $Text = [regex]::Replace(
            $Text,
            '(?m)^#define\s+LAYOUT\s+//\s*\r?\nLAYOUT\s*\r?\n',
            '',
            1)
        $Text = "#version 310 es`nlayout(local_size_x=8, local_size_y=8, local_size_z=1) in;`n" + $Text
    } else {
        $Text = "#version 310 es`n" + $Text
    }

    $Wrapped = Join-Path $WrapDir ((Split-Path $Item.P -Leaf) + "." + $Item.S)
    WriteUtf8NoBom $Wrapped $Text

    $Lines = & $Validator -S $Item.S $Wrapped 2>&1
    $Rc = $LASTEXITCODE
    foreach ($Line in $Lines) { $GlslOutput.Add([string]$Line) }
    if ($Rc -ne 0) {
        $GlslOutput | Set-Content -LiteralPath $GlslLog -Encoding UTF8
        Fail "glslangValidator failed for $($Item.P); see $GlslLog"
    }
}
$GlslOutput | Set-Content -LiteralPath $GlslLog -Encoding UTF8

Write-Host "Temporary-copy validation: PASS"

Write-Host "=== GATE 4: APPLY EXACT VALIDATED CANDIDATES ==="
foreach ($Rel in $Targets) {
    $From = Join-Path $Cand $Rel
    $Parent = Split-Path -Parent $Rel
    if ($Parent) { New-Item -ItemType Directory -Force -Path $Parent | Out-Null }
    Copy-Item -LiteralPath $From -Destination $Rel -Force
}

Hash-Protected $Targets $ProtectedAfter
if ((Get-Content $ProtectedBefore -Raw) -ne (Get-Content $ProtectedAfter -Raw)) {
    Fail "Protected tracked app source changed"
}

if (-not (Test-Path -LiteralPath 'local.properties')) { Fail "local.properties was lost" }
if (-not (Select-String -LiteralPath 'local.properties' -Pattern 'sdk.dir' -SimpleMatch -Quiet)) {
    Fail "sdk.dir was lost"
}

& git diff --check -- @Targets
if ($LASTEXITCODE -ne 0) { Fail "git diff --check failed" }

Write-Host "candidate/source validation PASS"
Write-Host "Temporary-copy validation: PASS"
Write-Host "PRE-BUILD SAFETY PROOF PASSED"

& git diff --binary HEAD -- app | Out-File -LiteralPath $PostPatch -Encoding utf8
if ($LASTEXITCODE -ne 0) { Fail "Post-edit patch failed" }

Write-Host "=== GATE 5: JAVAC PROOF ==="
$JdkCandidates = @(
    'C:\Program Files\Eclipse Adoptium\jdk-17.0.20.8-hotspot',
    'C:\Program Files\Android\Android Studio\jbr'
)
foreach ($Jdk in $JdkCandidates) {
    if (Test-Path (Join-Path $Jdk 'bin\java.exe')) {
        $env:JAVA_HOME = $Jdk
        break
    }
}
if (-not $env:JAVA_HOME -or -not (Test-Path (Join-Path $env:JAVA_HOME 'bin\java.exe'))) {
    Fail "Java 17 / Android Studio JBR not found"
}
$env:Path = "$env:JAVA_HOME\bin;$env:Path"

$OldEA = $ErrorActionPreference
try {
    $ErrorActionPreference = 'Continue'
    & .\gradlew.bat :app:compileDebugJavaWithJavac --stacktrace 2>&1 |
        Tee-Object -FilePath $JavacLog
    $JavacRc = $LASTEXITCODE
}
finally { $ErrorActionPreference = $OldEA }

if ($JavacRc -ne 0) { Fail "Javac failed; see $JavacLog" }
if (-not (ReadT $JavacLog).Contains('BUILD SUCCESSFUL')) {
    Fail "Javac BUILD SUCCESSFUL missing"
}
Write-Host "JAVAC PROOF PASSED"

Write-Host "=== GATE 6: BUILD 0.9726436 / 26436 ==="
try {
    $ErrorActionPreference = 'Continue'
    & .\gradlew.bat :app:assembleDebug --stacktrace 2>&1 |
        Tee-Object -FilePath $BuildLog
    $BuildRc = $LASTEXITCODE
}
finally { $ErrorActionPreference = $OldEA }

if ($BuildRc -ne 0) { Fail "Gradle build failed; see $BuildLog" }
if (-not (ReadT $BuildLog).Contains('BUILD SUCCESSFUL')) {
    Fail "BUILD SUCCESSFUL missing from build log"
}

$Built = Get-ChildItem -LiteralPath 'app\build\outputs\apk' -Recurse -File -Filter '*.apk' |
    Sort-Object LastWriteTime -Descending |
    Select-Object -First 1
if (-not $Built) { Fail "Built APK not found" }

Get-ChildItem -LiteralPath $Repo -File -Filter 'IrisCamera-*.apk' -ErrorAction SilentlyContinue |
    Remove-Item -Force
Move-Item -LiteralPath $Built.FullName -Destination $ApkOut -Force

Get-ChildItem -LiteralPath 'app\build' -Recurse -File -Filter '*.apk' -ErrorAction SilentlyContinue |
    Remove-Item -Force

@(
    '26436 WINDOWS INTEGRATED MIGRATION + BUILD'
    ('Timestamp: ' + (Get-Date -Format o))
